def longest_dup_substring(s):
    n = len(s)
    nums = [ord(c) - 97 for c in s]
    MOD = (1 << 61) - 1
    BASE = 26

    def search(length):
        h = 0
        power = 1
        for i in range(length):
            h = (h * BASE + nums[i]) % MOD
            if i < length - 1:
                power = (power * BASE) % MOD
        seen = {h: [0]}
        for start in range(1, n - length + 1):
            h = (h - nums[start - 1] * power) % MOD              # remove the leaving character
            h = (h * BASE + nums[start + length - 1]) % MOD        # add the entering character
            if h in seen:
                for idx in seen[h]:
                    if s[idx:idx + length] == s[start:start + length]:    # verify against collisions
                        return start
                seen[h].append(start)
            else:
                seen[h] = [start]
        return -1

    lo, hi = 1, n - 1
    result_start, result_len = -1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        idx = search(mid)
        if idx != -1:
            result_start, result_len = idx, mid
            lo = mid + 1                          # this length works, try longer
        else:
            hi = mid - 1                            # try shorter
    return s[result_start:result_start + result_len] if result_len > 0 else ''

