import java.util.*;

public class Main {
    static int n;
    static long[] nums;
    static final long MOD = (1L << 61) - 1;
    static final long BASE = 26;

    static int search(String s, int length) {
        long h = 0, power = 1;
        for (int i = 0; i < length; i++) {
            h = (h * BASE + nums[i]) % MOD;
            if (i < length - 1) power = (power * BASE) % MOD;
        }
        Map<Long, List<Integer>> seen = new HashMap<>();
        seen.computeIfAbsent(h, k -> new ArrayList<>()).add(0);
        for (int start = 1; start + length <= n; start++) {
            h = ((h - nums[start - 1] * power) % MOD + MOD) % MOD;   // remove leaving character
            h = (h * BASE + nums[start + length - 1]) % MOD;           // add entering character
            if (seen.containsKey(h)) {
                for (int idx : seen.get(h)) {
                    if (s.substring(idx, idx + length).equals(s.substring(start, start + length))) return start;  // verify
                }
                seen.get(h).add(start);
            } else {
                seen.computeIfAbsent(h, k -> new ArrayList<>()).add(start);
            }
        }
        return -1;
    }

    static String longestDupSubstring(String s) {
        n = s.length();
        nums = new long[n];
        for (int i = 0; i < n; i++) nums[i] = s.charAt(i) - 'a';
        int lo = 1, hi = n - 1, resStart = -1, resLen = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int idx = search(s, mid);
            if (idx != -1) { resStart = idx; resLen = mid; lo = mid + 1; }   // works, try longer
            else hi = mid - 1;                                                   // try shorter
        }
        return resLen > 0 ? s.substring(resStart, resStart + resLen) : "";
    }
}

