#include <bits/stdc++.h>
using namespace std;

const long long MOD = (1LL << 61) - 1;
const long long BASE = 26;

int search(const string& s, vector<long long>& nums, int length) {
    int n = s.size();
    long long h = 0, power = 1;
    for (int i = 0; i < length; i++) {
        h = (h * BASE + nums[i]) % MOD;
        if (i < length - 1) power = (power * BASE) % MOD;
    }
    unordered_map<long long, vector<int>> seen;
    seen[h].push_back(0);
    for (int start = 1; start + length <= n; start++) {
        h = ((h - nums[start - 1] * power) % MOD + MOD) % MOD;     // remove leaving character
        h = (h * BASE + nums[start + length - 1]) % MOD;             // add entering character
        auto it = seen.find(h);
        if (it != seen.end()) {
            for (int idx : it->second) {
                if (s.compare(idx, length, s, start, length) == 0) return start;   // verify
            }
            it->second.push_back(start);
        } else {
            seen[h].push_back(start);
        }
    }
    return -1;
}

string longestDupSubstring(string s) {
    int n = s.size();
    vector<long long> nums(n);
    for (int i = 0; i < n; i++) nums[i] = s[i] - 'a';
    int lo = 1, hi = n - 1, resStart = -1, resLen = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int idx = search(s, nums, mid);
        if (idx != -1) { resStart = idx; resLen = mid; lo = mid + 1; }   // works, try longer
        else hi = mid - 1;                                                   // try shorter
    }
    return resLen > 0 ? s.substr(resStart, resLen) : "";
}
